function memberCard(member){const row=document.createElement('article');row.className='member-card';const identity=document.createElement('div');identity.className='member-identity';const name=document.createElement('strong');name.textContent=member.displayName||'Unnamed member';const email=document.createElement('span');email.textContent=member.email||'No email';const badges=document.createElement('div');badges.className='member-badges';const role=document.createElement('span');role.className='badge';role.textContent=member.role||'member';const status=document.createElement('span');status.className=`badge status-${member.status||'pending'}`;status.textContent=member.status||'pending';badges.append(role,status);identity.append(name,email,badges);row.append(identity);if(member.role!=='owner'){const actions=document.createElement('div');actions.className='member-actions';[['Approve','approved'],['Reject','rejected'],['Suspend','suspended']].forEach(([label,value])=>{const button=document.createElement('button');button.type='button';button.className=value==='approved'?'approve-btn':'secondary small';button.textContent=label;button.disabled=member.status===value;button.addEventListener('click',()=>{if(confirmAction(label,member))changeStatus(member,value)});actions.append(button)});if(currentMember?.role==='owner'&&member.status==='approved'){const roleButton=document.createElement('button');roleButton.type='button';roleButton.className='secondary small role-btn';const promoting=member.role!=='admin';roleButton.textContent=promoting?'Promote to admin':'Demote to member';roleButton.addEventListener('click',()=>{const action=promoting?'Promote to admin':'Demote to member';if(confirmAction(action,member))changeRole(member,promoting?'admin':'member')});actions.append(roleButton)}row.append(actions)}return row}
function updateAdminStats(members){const counts={approved:0,pending:0,suspended:0,rejected:0};members.forEach(member=>{if(Object.hasOwn(counts,member.status))counts[member.status]++});document.querySelector('#stat-total').textContent=members.length;Object.entries(counts).forEach(([status,count])=>document.querySelector(`#stat-${status}`).textContent=count);pendingAlert.textContent=counts.pending?`${counts.pending} awaiting approval`:'';pendingAlert.classList.toggle('hidden',!counts.pending)}
function formatActivityTime(timestamp){if(!timestamp?.toDate)return 'Just now';return timestamp.toDate().toLocaleString([],{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})}
function renderActivity(snapshot){activityList.replaceChildren();if(snapshot.empty){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=5;td.className='activity-empty';td.textContent='No activity recorded yet.';tr.append(td);activityList.append(tr);return}snapshot.forEach(d=>{const a=d.data(),tr=document.createElement('tr');const values=[formatActivityTime(a.createdAt),a.type==='sign_in'?'Sign in':a.type==='role_change'?'Role change':'Status change',a.type==='sign_in'?`${a.memberName||'Member'}${a.email?` — ${a.email}`:''}`:a.memberName||'Member',a.type==='sign_in'?'—':a.actorName||'Administrator',a.type==='sign_in'?'Successful':`${a.from||'—'} → ${a.to||'—'}`];values.forEach(value=>{const td=document.createElement('td');td.textContent=value;tr.append(td)});activityList.append(tr)})}
async function loadActivity(){if(currentMember?.role!=='owner')return;try{const q=query(collection(db,'activityLog'),orderBy('createdAt','desc'),limit(100));renderActivity(await getDocs(q))}catch(err){console.error(err);activityList.innerHTML='<tr><td colspan="5" class="activity-empty">Could not load activity.</td></tr>'}}
async function loadMembers(){if(currentMember?.role!=='owner')return;adminMessage.textContent='Loading crew…';memberList.replaceChildren();try{const snap=await getDocs(collection(db,'members'));const members=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>{const order={pending:0,approved:1,suspended:2,rejected:3};return (order[a.status]??9)-(order[b.status]??9)});updateAdminStats(members);members.forEach(m=>memberList.append(memberCard(m)));await loadActivity();adminMessage.textContent=`Updated ${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}.`}catch(err){console.error(err);adminMessage.textContent=`Could not load crew. ${err.code||''}`}}
async function changeStatus(member,status){adminMessage.textContent='Updating member…';try{const batch=writeBatch(db),memberRef=doc(db,'members',member.id||member.uid),activityRef=doc(collection(db,'activityLog'));batch.update(memberRef,{status,updatedAt:serverTimestamp()});batch.set(activityRef,activityPayload('status_change',member,member.status||'',status));await batch.commit();await loadMembers()}catch(err){console.error(err);adminMessage.textContent=`Update failed. ${err.code||''}`}}
async function changeRole(member,role){if(currentMember?.role!=='owner')return;adminMessage.textContent=role==='admin'?'Promoting member…':'Removing admin role…';try{const batch=writeBatch(db),memberRef=doc(db,'members',member.id||member.uid),activityRef=doc(collection(db,'activityLog'));batch.update(memberRef,{role,updatedAt:serverTimestamp()});batch.set(activityRef,activityPayload('role_change',member,member.role||'',role));await batch.commit();await loadMembers()}catch(err){console.error(err);adminMessage.textContent=`Role update failed. ${err.code||''}`}}
async function activateMember(member){currentMember=member;showGate(member.status);const canManage=member.status==='approved'&&member.role==='owner';adminPanel.classList.toggle('hidden',!canManage);document.querySelector('#owner-circles-open')?.classList.toggle('hidden',member.role!=='owner');if(canManage)await loadMembers();if(member.status==='approved')await loadRooms()}

function canEnterRoom(room){return room.access==='open'||room.createdBy===auth.currentUser?.uid||currentMember?.role==='owner'||(Array.isArray(room.memberUids)&&room.memberUids.includes(auth.currentUser?.uid))}
function canManageRoom(room){return currentMember?.role==='owner'||(currentMember?.role==='admin'&&room.id!=='main'&&room.createdBy===auth.currentUser?.uid)}
function roomCard(room){const card=document.createElement('article');card.className='custom-room-card';const info=document.createElement('div'),name=document.createElement('strong'),desc=document.createElement('p'),meta=document.createElement('span');name.textContent=room.name;desc.textContent=room.description||'Private SỌ̀RỌ̀ circle';meta.textContent=room.access==='invite'?'Invite only':'Open to approved crew';info.append(name,desc,meta);const actions=document.createElement('div');actions.className='room-card-actions';if(canEnterRoom(room)&&room.status!=='closed'){const enter=document.createElement('button');enter.className='primary small';enter.type='button';enter.textContent='Enter';enter.addEventListener('click',()=>openRoom(room));actions.append(enter)}if(canManageRoom(room)){const manage=document.createElement('button');manage.className='secondary small';manage.type='button';manage.textContent='Manage';manage.addEventListener('click',()=>openRoomManagement(room));actions.append(manage)}card.append(info,actions);return card}
function renderOwnerCircles(){if(currentMember?.role!=='owner')return;const term=(circlesSearch.value||'').trim().toLowerCase(),status=circlesStatusFilter.value,access=circlesAccessFilter.value,creator=circlesCreatorFilter.value;const filtered=ownerCircles.filter(r=>(!term||[r.name,r.createdByName].some(v=>String(v||'').toLowerCase().includes(term)))&&(!status||r.status===status)&&(!access||r.access===access)&&(!creator||r.createdBy===creator));circlesDashboardList.replaceChildren();if(!filtered.length){const empty=document.createElement('p');empty.className='owner-circles-empty';empty.textContent='No Circles match the current search and filters.';circlesDashboardList.append(empty)}filtered.forEach(room=>{const row=document.createElement('article');row.className='owner-circle-row';const info=document.createElement('div');info.className='owner-circle-info';const name=document.createElement('strong');name.textContent=room.name||'Unnamed Circle';const meta=document.createElement('span');meta.textContent=`Created by ${room.createdByName||'Administrator'} • ${room.access==='invite'?'Invite Only':'Open'} • ${room.status==='closed'?'Closed':'Active'}`;info.append(name,meta);const manage=document.createElement('button');manage.type='button';manage.className='secondary small';manage.textContent='Manage';manage.addEventListener('click',()=>openRoomManagement(room));row.append(info,manage);circlesDashboardList.append(row)});document.querySelector('#circle-stat-total').textContent=ownerCircles.length;document.querySelector('#circle-stat-active').textContent=ownerCircles.filter(r=>r.status!=='closed').length;document.querySelector('#circle-stat-closed').textContent=ownerCircles.filter(r=>r.status==='closed').length;document.querySelector('#circle-stat-open').textContent=ownerCircles.filter(r=>r.access==='open').length;document.querySelector('#circle-stat-invite').textContent=ownerCircles.filter(r=>r.access==='invite').length}
async function loadOwnerCirclesDashboard(){if(currentMember?.role!=='owner')return;circlesDashboardMessage.textContent='Loading Circles…';try{const snap=await getDocs(collection(db,'rooms'));ownerCircles=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>(a.name||'').localeCompare(b.name||''));const creators=[...new Map(ownerCircles.filter(r=>r.createdBy).map(r=>[r.createdBy,r.createdByName||'Administrator'])).entries()].sort((a,b)=>a[1].localeCompare(b[1]));circlesCreatorFilter.innerHTML='<option value="">All creators</option>';creators.forEach(([uid,name])=>{const option=document.createElement('option');option.value=uid;option.textContent=name;circlesCreatorFilter.append(option)});renderOwnerCircles();circlesDashboardMessage.textContent=`Updated ${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}.`}catch(err){console.error(err);circlesDashboardMessage.textContent=`Could not load Circles. ${err.code||''}`}}
