async function cleanupLegacyUkRoom(){if(currentMember?.role!=='owner')return;try{const snap=await getDocs(collection(db,'rooms'));const legacy=snap.docs.filter(d=>String(d.data().name||'').trim().toUpperCase()==='UK ROOM');for(const legacyDoc of legacy){const messages=await getDocs(collection(db,'rooms',legacyDoc.id,'messages'));if(messages.size>499){console.warn('Legacy UK ROOM cleanup skipped: too many messages.');continue}const batch=writeBatch(db);messages.docs.forEach(messageDoc=>batch.delete(messageDoc.ref));batch.delete(legacyDoc.ref);await batch.commit()}}catch(err){console.error('Legacy UK ROOM startup cleanup failed',err)}}
