tingsSaveProfile?.addEventListener('click',async()=>{const name=settingsDisplayName.value.trim();if(!name)return;settingsSaveProfile.disabled=true;settingsProfileMessage.textContent='Saving…';try{await updateProfile(auth.currentUser,{displayName:name});await updateDoc(doc(db,'members',auth.currentUser.uid),{displayName:name});currentMember.displayName=name;renderSettings();settingsProfileMessage.textContent='Profile saved.'}catch(err){console.error(err);settingsProfileMessage.textContent='Could not save profile.'}finally{settingsSaveProfile.disabled=false}});settingsDirectoryVisible?.addEventListener('change',async()=>{const value=settingsDirectoryVisible.checked;try{await updateDoc(doc(db,'members',auth.currentUser.uid),{directoryVisible:value});currentMember.directoryVisible=value}catch(err){console.error(err);settingsDirectoryVisible.checked=!value}});settingsCircleResourcesSave?.addEventListener('click',async()=>{if(!currentRoom||currentRoom.id==='main'||!canManageRoom(currentRoom))return;const enabledResources=[...settingsCircleResourceList.querySelectorAll('input[data-resource-id]:checked')].map(i=>i.dataset.resourceId);settingsCircleResourcesSave.disabled=true;settingsCircleResourcesMessage.textContent='Saving…';try{await updateDoc(doc(db,'rooms',currentRoom.id),{enabledResources,updatedAt:serverTimestamp()});currentRoom={...currentRoom,enabledResources};const i=visibleRooms.findIndex(r=>r.id===currentRoom.id);if(i>=0)visibleRooms[i]={...visibleRooms[i],enabledResources};settingsCircleResourcesMessage.textContent='Circle resources saved.'}catch(err){console.error(err);settingsCircleResourcesMessage.textContent='Could not save Circle resources.'}finally{settingsCircleResourcesSave.disabled=false}});settingsSignout?.addEventListener('click',()=>signOut(auth));
