async function openRoomManagement(room){if(room.id==='main'){if(currentMember?.role!=='owner')return;gate.classList.remove('hidden');roomDirectory.classList.add('hidden');adminPanel.classList.remove('hidden');await loadMembers();return}if(!canManageRoom(room))return;managedRoom=room;roomDirectory.classList.add('hidden');crewRoom.classList.add('hidden');gate.classList.add('hidden');roomManagement.classList.remove('hidden');roomManagementMessage.textContent='Loading room management…';roomManagementTitle.textContent=room.name;roomDetailsForm.elements.name.value=room.name||'';roomDetailsForm.elements.description.value=room.description||'';roomAccessForm.elements.access.value=room.access||'open';roomCreator.textContent=room.createdByName||'Administrator';roomCreated.textContent=managementDate(room.createdAt);roomStatusButton.textContent=room.status==='closed'?'Reopen room':'Close room';roomStatusButton.dataset.status=room.status||'active';roomDeleteButton.classList.toggle('hidden',room.id==='main');try{const [membersSnap,messagesSnap]=await Promise.all([getDocs(collection(db,'members')),getDocs(collection(db,'rooms',room.id,'messages'))]);const members=membersSnap.docs.map(d=>({id:d.id,...d.data()})).filter(m=>m.status==='approved').sort((a,b)=>(a.displayName||a.email||'').localeCompare(b.displayName||b.email||''));roomMemberList.replaceChildren();members.forEach(member=>{const row=document.createElement('label');row.className='room-member-row';const identity=document.createElement('span');identity.innerHTML='';const strong=document.createElement('strong');strong.textContent=member.displayName||'Unnamed member';const email=document.createElement('small');email.textContent=member.email||'';identity.append(strong,email);const toggle=document.createElement('input');toggle.type='checkbox';toggle.checked=member.id===room.createdBy||currentMember?.role==='owner'&&member.role==='owner'||(room.memberUids||[]).includes(member.id);toggle.disabled=member.id===room.createdBy||member.role==='owner';toggle.dataset.uid=member.id;row.append(identity,toggle);roomMemberList.append(row)});roomMemberCount.textContent=String([room.createdBy,...(room.memberUids||[])].filter((uid,i,a)=>uid&&a.indexOf(uid)===i).length);roomMessageCount.textContent=String(messagesSnap.size);roomAccessConfirmation.textContent='';roomResourcesConfirmation.textContent='';roomResourceList.replaceChildren();const selected=Array.isArray(room.enabledResources)?room.enabledResources:RESOURCE_CATALOG.map(r=>r[0]);RESOURCE_CATALOG.forEach(([id,name])=>{const label=document.createElement('label');label.className='resource-toggle-row';const text=document.createElement('span');text.textContent=name;const toggle=document.createElement('input');toggle.type='checkbox';toggle.className='resource-toggle';toggle.dataset.resourceId=id;toggle.checked=selected.includes(id);label.append(text,toggle);roomResourceList.append(label)});roomManagementMessage.textContent=''}catch(err){console.error(err);roomManagementMessage.textContent=`Could not load room management. ${err.code||''}`}}
roomDetailsForm.addEventListener('submit',async e=>{e.preventDefault();if(!managedRoom||!canManageRoom(managedRoom))return;const name=roomDetailsForm.elements.name.value.trim().slice(0,60),description=roomDetailsForm.elements.description.value.trim().slice(0,240);if(!name)return;try{await updateDoc(doc(db,'rooms',managedRoom.id),{name,description,updatedAt:serverTimestamp()});managedRoom={...managedRoom,name,description};roomManagementTitle.textContent=name;roomManagementMessage.textContent='Circle details saved.'}catch(err){console.error(err);roomManagementMessage.textContent=`Save failed. ${err.code||''}`}})
roomAccessForm.addEventListener('submit',async e=>{e.preventDefault();if(!managedRoom||!canManageRoom(managedRoom))return;const access=roomAccessForm.elements.access.value;const memberUids=[...new Set([...roomMemberList.querySelectorAll('input[data-uid]:checked')].map(i=>i.dataset.uid).filter(uid=>uid&&uid!==managedRoom.createdBy))];const count=1+memberUids.length;if(!window.confirm(`Save access for ${count} Circle member${count===1?'':'s'}?`))return;roomAccessSave.disabled=true;roomAccessSave.textContent='Saving…';roomAccessConfirmation.textContent='Saving member access…';try{const ref=doc(db,'rooms',managedRoom.id);await updateDoc(ref,{access,memberUids,updatedAt:serverTimestamp()});const verify=await getDoc(ref);if(!verify.exists())throw new Error('Circle could not be reloaded after saving.');const saved=verify.data(),savedUids=Array.isArray(saved.memberUids)?saved.memberUids:[];if(saved.access!==access||savedUids.length!==memberUids.length||memberUids.some(uid=>!savedUids.includes(uid)))throw new Error('Saved member access did not match the selected members.');managedRoom={id:verify.id,...saved};const visibleIndex=visibleRooms.findIndex(room=>room.id===managedRoom.id);if(visibleIndex>=0)visibleRooms[visibleIndex]={...managedRoom};roomMemberCount.textContent=String(1+savedUids.length);roomAccessConfirmation.textContent=`Saved. ${1+savedUids.length} Circle member${1+savedUids.length===1?'':'s'} assigned.`;roomManagementMessage.textContent='Member access saved and verified.';renderSidebarCircles()}catch(err){console.error(err);roomAccessConfirmation.textContent=`Access update failed: ${err.message||err.code||'Unknown error'}`;roomManagementMessage.textContent='Member access was not saved.'}finally{roomAccessSave.disabled=false;roomAccessSave.textContent='Save member access'}})
roomResourcesSave.addEventListener('click',async()=>{if(!managedRoom||!canManageRoom(managedRoom))return;const enabledResources=[...roomResourceList.querySelectorAll('input[data-resource-id]:checked')].map(i=>i.dataset.resourceId);roomResourcesSave.disabled=true;roomResourcesConfirmation.textContent='Saving…';try{await updateDoc(doc(db,'rooms',managedRoom.id),{enabledResources,updatedAt:serverTimestamp()});managedRoom={...managedRoom,enabledResources};const i=visibleRooms.findIndex(r=>r.id===managedRoom.id);if(i>=0)visibleRooms[i]={...visibleRooms[i],enabledResources};if(currentRoom?.id===managedRoom.id)currentRoom={...currentRoom,enabledResources};roomResourcesConfirmation.textContent='Circle resources saved.'}catch(err){console.error(err);roomResourcesConfirmation.textContent='Could not save Circle resources.'}finally{roomResourcesSave.disabled=false}});roomStatusButton.addEventListener('click',async()=>{if(!managedRoom||!canManageRoom(managedRoom))return;const next=managedRoom.status==='closed'?'active':'closed';if(!window.confirm(next==='closed'?'Close this room? Members will not be able to enter or post until it is reopened.':'Reopen this room?'))return;try{await updateDoc(doc(db,'rooms',managedRoom.id),{status:next,updatedAt:serverTimestamp()});managedRoom={...managedRoom,status:next};roomStatusButton.textContent=next==='closed'?'Reopen room':'Close room';roomManagementMessage.textContent=next==='closed'?'Circle closed.':'Circle reopened.'}catch(err){console.error(err);roomManagementMessage.textContent=`Status update failed. ${err.code||''}`}})
roomDeleteButton.addEventListener('click',()=>{if(!managedRoom||managedRoom.id==='main'||!canManageRoom(managedRoom))return;roomDeleteName.textContent=managedRoom.name;roomDeleteDialog.showModal()});
roomDeleteCancel.addEventListener('click',()=>roomDeleteDialog.close());
roomDeleteConfirm.addEventListener('click',async()=>{if(!managedRoom||managedRoom.id==='main'||!canManageRoom(managedRoom))return;const roomId=managedRoom.id,roomName=managedRoom.name;roomDeleteConfirm.disabled=true;roomDeleteCancel.disabled=true;roomDeleteConfirm.textContent='Deleting…';try{const messages=await getDocs(collection(db,'rooms',roomId,'messages'));if(messages.size>499)throw new Error('This circle has too many messages for safe browser deletion. Contact the Owner to delete it in smaller batches.');const batch=writeBatch(db);messages.docs.forEach(messageDoc=>batch.delete(messageDoc.ref));batch.delete(doc(db,'rooms',roomId));await batch.commit();const verify=await getDoc(doc(db,'rooms',roomId));if(verify.exists())throw new Error('Firestore still reports the circle document after deletion.');roomDeleteDialog.close();managedRoom=null;roomManagement.classList.add('hidden');roomDirectory.classList.remove('hidden');roomCreateMessage.textContent=`"${roomName}" was permanently deleted.`;await loadRooms()}catch(err){console.error('Room deletion failed',err);roomDeleteDialog.close();roomManagementMessage.textContent=`Delete failed: ${err.message||err.code||'Unknown Firebase error.'}`}finally{roomDeleteConfirm.disabled=false;roomDeleteCancel.disabled=false;roomDeleteConfirm.textContent='Permanently delete room'}})
