function formatTime(timestamp){if(!timestamp?.toDate)return 'sending…';return timestamp.toDate().toLocaleString([],{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}
function selectReply(id,data){replyTarget={id,displayName:data.displayName||'Crew member',text:data.text||''};replyName.textContent=replyTarget.displayName;replyText.textContent=replyTarget.text.length>120?`${replyTarget.text.slice(0,120)}…`:replyTarget.text;replyBar.classList.remove('hidden');messageInput.focus()}
function replyPreview(data){if(!data.replyTo)return null;const preview=document.createElement('button');preview.type='button';preview.className='reply-preview';const name=document.createElement('strong');name.textContent=data.replyTo.displayName||'Crew member';const text=document.createElement('span');text.textContent=data.replyTo.text||'Message';preview.append(name,text);preview.addEventListener('click',()=>{const target=document.querySelector(`[data-message-id="${CSS.escape(data.replyTo.id)}"]`);if(target){target.scrollIntoView({behavior:'smooth',block:'center'});target.classList.add('message-highlight');setTimeout(()=>target.classList.remove('message-highlight'),1200)}});return preview}
function youtubeVideoId(url){try{const u=new URL(url),host=u.hostname.replace(/^www\./,'').toLowerCase();if(host==='youtu.be')return u.pathname.split('/').filter(Boolean)[0]||null;if(host==='youtube.com'||host==='m.youtube.com'||host==='music.youtube.com'){if(u.pathname==='/watch')return u.searchParams.get('v');const match=u.pathname.match(/^\/(?:shorts|live|embed)\/([^/?#]+)/);return match?.[1]||null}}catch{}return null}function messageBody(text){const wrap=document.createElement('div'),body=document.createElement('p'),embeds=document.createElement('div'),urlPattern=/(https?:\/\/[^\s<]+[^\s<.,;:!?\)\]\}])/gi;embeds.className='message-embeds';let last=0;String(text||'').replace(urlPattern,(url,offset)=>{body.append(document.createTextNode(String(text||'').slice(last,offset)));const link=document.createElement('a');link.href=url;link.textContent=url;link.target='_blank';link.rel='noopener noreferrer';body.append(link);const videoId=youtubeVideoId(url);if(videoId&&/^[A-Za-z0-9_-]{11}$/.test(videoId)){const frame=document.createElement('iframe');frame.className='youtube-embed';frame.src=`https://www.youtube-nocookie.com/embed/${videoId}`;frame.title='YouTube video';frame.loading='lazy';frame.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';frame.referrerPolicy='strict-origin-when-cross-origin';frame.allowFullscreen=true;embeds.append(frame)}last=offset+url.length;return url});body.append(document.createTextNode(String(text||'').slice(last)));wrap.append(body);if(embeds.childElementCount)wrap.append(embeds);return wrap}
async function renderMessages(snapshot){messageList.replaceChildren();const memberPhotos=new Map();try{const members=await getDocs(query(collection(db,'members'),where('status','==','approved')));members.forEach(m=>{const data=m.data();memberPhotos.set(data.uid,{photoURL:data.photoURL||'',displayName:data.displayName||''})})}catch(err){console.error('Could not load message profile pictures',err)}if(snapshot.empty){const empty=document.createElement('p');empty.className='room-empty';empty.textContent='No messages yet. Start the crew conversation.';messageList.append(empty);return}snapshot.forEach(d=>{const data=d.data(),item=document.createElement('article');item.dataset.messageId=d.id;item.className=`chat-message${data.uid===auth.currentUser?.uid?' own':''}`;const identity=document.createElement('div');identity.className='message-identity';const profile=memberPhotos.get(data.uid)||{},avatar=profile.photoURL?document.createElement('img'):document.createElement('span');avatar.className='message-avatar';if(profile.photoURL){avatar.src=profile.photoURL;avatar.alt='';avatar.referrerPolicy='no-referrer'}else avatar.textContent=(data.displayName||profile.displayName||'M').trim().charAt(0).toUpperCase()||'M';const meta=document.createElement('div');meta.className='message-meta';const sender=document.createElement('strong');sender.textContent=data.displayName||profile.displayName||'Crew member';const time=document.createElement('time');time.textContent=formatTime(data.createdAt);const body=messageBody(data.text||'');const reply=replyPreview(data);const actions=document.createElement('div');actions.className='message-actions';const replyButton=document.createElement('button');replyButton.type='button';replyButton.textContent='Reply';replyButton.addEventListener('click',()=>selectReply(d.id,data));actions.append(replyButton);meta.append(sender,time);identity.append(avatar,meta);item.append(identity);if(reply)item.append(reply);item.append(body,actions);messageList.append(item)});messageList.scrollTop=messageList.scrollHeight}
function openCrewRoom(){showRooms()}
adminCircleSearch?.addEventListener('input',renderRooms);enterCrew.addEventListener('click',openCrewRoom);backRooms.addEventListener('click',showRooms);document.querySelector('#directory-signout').addEventListener('click',()=>signOut(auth));document.querySelector('#cancel-reply').addEventListener('click',clearReply);document.querySelectorAll('[data-auth-open]').forEach(b=>b.addEventListener('click',()=>dialog.showModal()));document.querySelector('.close').addEventListener('click',()=>dialog.close());document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));document.querySelector('#gate-signout').addEventListener('click',()=>signOut(auth));document.querySelector('#room-signout').addEventListener('click',()=>signOut(auth));document.querySelector('#refresh-members').addEventListener('click',loadMembers);document.querySelector('#owner-circles-open')?.addEventListener('click',openOwnerCirclesDashboard);document.querySelector('#circles-dashboard-back')?.addEventListener('click',()=>{circlesDashboard.classList.add('hidden');gate.classList.remove('hidden')});document.querySelector('#circles-dashboard-global')?.addEventListener('click',()=>openRoomManagement({id:'main',name:'The Global Circle',description:'The original SỌ̀RỌ̀ global circle.',access:'open',status:'active',createdBy:'main'}));[circlesSearch,circlesStatusFilter,circlesAccessFilter,circlesCreatorFilter].forEach(el=>el?.addEventListener(el===circlesSearch?'input':'change',renderOwnerCircles));
messageForm.addEventListener('submit',async e=>{e.preventDefault();const text=messageInput.value.trim();if(!text||!currentMember||currentMember.status!=='approved'||!auth.currentUser)return;const button=messageForm.querySelector('button'),payload={text,uid:auth.currentUser.uid,displayName:currentMember.displayName||auth.currentUser.displayName||'Crew member',createdAt:serverTimestamp()};if(replyTarget)payload.replyTo={id:replyTarget.id,displayName:replyTarget.displayName,text:replyTarget.text.slice(0,240)};button.disabled=true;roomMessage.textContent='';try{const target=currentRoom?.id&&currentRoom.id!=='main'?collection(db,'rooms',currentRoom.id,'messages'):collection(db,'messages');await addDoc(target,payload);messageInput.value='';clearReply();messageInput.focus()}catch(err){console.error(err);roomMessage.textContent=`Message not sent. ${err.code||''}`}finally{button.disabled=false}});
form.addEventListener('submit',async e=>{e.preventDefault();setMessage('Working…');const email=document.querySelector('#email').value.trim(),password=document.querySelector('#password').value,name=document.querySelector('#display-name').value.trim();try{if(mode==='signup'){const cred=await createUserWithEmailAndPassword(auth,email,password);if(name)await updateProfile(cred.user,{displayName:name});await ensureMember(cred.user);await sendEmailVerification(cred.user);dialog.close();showGate('pending')}else{const cred=await signInWithEmailAndPassword(auth,email,password);if(!cred.user.emailVerified){await sendEmailVerification(cred.user);setMessage('Verify your email first. A new verification email has been sent.',true);return}const member=await ensureMember(cred.user);await logSignIn(member);dialog.close();await activateMember(member)}}catch(err){setMessage(authError(err),true)}});
document.querySelector('#google-auth').addEventListener('click',async e=>{e.preventDefault();setMessage('Opening Google account selection…');try{const cred=await signInWithPopup(auth,google);setMessage('Google account connected. Checking crew access…');const member=await ensureMember(cred.user);await logSignIn(member);dialog.close();await activateMember(member)}catch(err){console.error('Google popup sign-in failed',err);if(err?.code==='auth/popup-closed-by-user')setMessage('Google sign-in window was closed before sign-in completed. Please try again.',true);else if(err?.code==='auth/popup-blocked')setMessage('Your browser blocked the Google sign-in window. Allow pop-ups for this site and try again. [auth/popup-blocked]',true);else if(err?.code==='auth/unauthorized-domain')setMessage('This SỌ̀RỌ̀ web address is not authorized in Firebase Authentication. [auth/unauthorized-domain]',true);else setMessage(authError(err,'Google sign-in failed.'),true)}});
onAuthStateChanged(auth,async user=>{if(!user){hideGate();return}try{if(user.providerData.some(p=>p.providerId==='password')&&!user.emailVerified){showGate('pending');document.querySelector('#gate-title').textContent='Verify your email';document.querySelector('#gate-copy').textContent='Check your inbox and verify your email address. After verification, sign in again. Your membership will then remain pending until an administrator approves it.';return}await activateMember(await ensureMember(user))}catch(e){console.error(e)}});
setMode('signin');

let soroGlobe=null,soroSelfPoint=null;let locationUnsubscribe=null,sharedLocationPoints=[];
function ensureSoroGlobe(){if(soroGlobe||!memberMapEl||typeof window.Globe==='undefined')return;soroGlobe=window.Globe().width(memberMapEl.clientWidth).height(memberMapEl.clientHeight).globeTileEngineUrl((x,y,l)=>`https://tile.openstreetmap.org/${l}/${x}/${y}.png`).backgroundImageUrl('https://unpkg.com/three-globe/example/img/night-sky.png').atmosphereColor('#c79a45').atmosphereAltitude(.14).showGraticules(true).showAtmosphere(true).htmlLat('latitude').htmlLng('longitude').htmlAltitude(.00008).htmlElement(p=>{const el=document.createElement('button');el.type='button';el.className='soro-location-pin '+(p.mine?'mine':'member');el.title=(p.displayName||'SORO member')+(p.accuracy?' — accuracy ±'+Math.round(p.accuracy)+' m':'');el.setAttribute('aria-label',el.title);el.innerHTML='<span></span>';el.addEventListener('click',()=>{const controls=soroGlobe?.controls();if(controls)controls.autoRotate=false;soroGlobe?.pointOfView({lat:p.latitude,lng:p.longitude,altitude:.00025},2200);setMapStatus((p.mine?'Your location':'Location: '+(p.displayName||'SORO member'))+(p.accuracy?' — GPS accuracy ±'+Math.round(p.accuracy)+' m':''));});return el})(memberMapEl);soroGlobe.pointOfView({lat:9,lng:15,altitude:2.25},0);const controls=soroGlobe.controls();if(controls){controls.autoRotate=true;controls.autoRotateSpeed=.25;controls.minDistance=100.02;controls.maxDistance=900}window.addEventListener('resize',()=>{if(soroGlobe&&!mapView?.classList.contains('hidden'))soroGlobe.width(memberMapEl.clientWidth).height(memberMapEl.clientHeight)})}
function refreshSoroGlobePoints(){if(!soroGlobe)return;const points=[...sharedLocationPoints];if(soroSelfPoint&&!points.some(p=>p.uid===soroSelfPoint.uid))points.push(soroSelfPoint);soroGlobe.htmlElementsData(points)}
function hideMapView(){mapView?.classList.add('hidden');sidebarMapButton?.classList.remove('active')}
function showMap(){if(!currentRoom)return;clearReply();stopEvents();messageList.classList.add('hidden');messageForm.classList.add('hidden');replyBar.classList.add('hidden');eventsView.classList.add('hidden');resourcesView.classList.add('hidden');proverbsView.classList.add('hidden');settingsView.classList.add('hidden');currencyView.classList.add('hidden');mapView.classList.remove('hidden');[sidebarCirclesButton,sidebarMembersButton,sidebarEventsButton,sidebarResourcesButton,sidebarSettingsButton].forEach(b=>b?.classList.remove('active'));sidebarMapButton.classList.add('active');ensureSoroGlobe();watchSharedLocations();setTimeout(()=>{if(soroGlobe)soroGlobe.width(memberMapEl.clientWidth).height(memberMapEl.clientHeight)},0)}
function setMapStatus(message){if(mapMessage)mapMessage.textContent=message;else window.alert(message)}
async function locateSelf(){setMapStatus('My Location button pressed…');if(!window.isSecureContext){setMapStatus('Location requires a secure HTTPS connection.');return}if(!navigator.geolocation){setMapStatus('Location is not supported on this device.');return}if(mapMyLocation)mapMyLocation.disabled=true;let permission='unknown';try{if(navigator.permissions?.query){permission=(await navigator.permissions.query({name:'geolocation'})).state}}catch(error){console.warn('SORO could not read geolocation permission state',error)}if(permission==='denied'){setMapStatus('Location is blocked for this site. Open Brave site settings for SỌ̀RỌ̀, set Location to Allow, reload the page, then try again.');if(mapMyLocation)mapMyLocation.disabled=false;return}setMapStatus(permission==='granted'?'Location permission is allowed. Getting GPS position…':'Waiting for browser location permission…');navigator.geolocation.getCurrentPosition(pos=>{ensureSoroGlobe();const lat=pos.coords.latitude,lng=pos.coords.longitude;soroSelfPoint={uid:'local-'+(auth.currentUser?.uid||'self'),displayName:'Your current location',latitude:lat,longitude:lng,accuracy:pos.coords.accuracy,mine:true};refreshSoroGlobePoints();const controls=soroGlobe?.controls();if(controls)controls.autoRotate=false;soroGlobe?.pointOfView({lat,lng,altitude:.00025},2200);setMapStatus('Location found. White marker shows your position. It has not been shared.');if(mapMyLocation)mapMyLocation.disabled=false},err=>{console.error('SORO geolocation failed',err);setMapStatus(err.code===1?'Location permission was denied or blocked for this site. Check Brave site settings for SỌ̀RỌ̀ and allow Location.':err.code===2?'Your device could not determine its location. Check Location/GPS and try again.':err.code===3?'Location request timed out. Check Location/GPS and try again.':'Could not get your location.');if(mapMyLocation)mapMyLocation.disabled=false},{enableHighAccuracy:true,timeout:20000,maximumAge:0})}
function closeMobileNav(){chatLayout?.classList.remove('mobile-nav-open');mobileMenuToggle?.setAttribute('aria-expanded','false');mobileMenuToggle?.setAttribute('aria-label','Open navigation')}
mobileMenuToggle?.addEventListener('click',()=>{const open=chatLayout?.classList.toggle('mobile-nav-open');mobileMenuToggle.setAttribute('aria-expanded',open?'true':'false');mobileMenuToggle.setAttribute('aria-label',open?'Close navigation':'Open navigation')});
document.querySelector('.chat-sidebar-nav')?.addEventListener('click',event=>{if(event.target.closest('button'))closeMobileNav()});
sidebarMapButton?.addEventListener('click',showMap);mapMyLocation?.addEventListener('click',locateSelf);mapShareLocation?.addEventListener('click',()=>{mapSharePanel.classList.remove('hidden');mapMessage.textContent='Choose how long to share your precise location.'});mapShareCancel?.addEventListener('click',()=>{mapSharePanel.classList.add('hidden');mapMessage.textContent=''});
function escapeMapHtml(value){const el=document.createElement('span');el.textContent=String(value??'');return el.innerHTML}
function renderSharedLocations(snap){const now=Date.now();sharedLocationPoints=[];snap.forEach(d=>{const x=d.data(),expiry=x.expiresAt?.toMillis?.()||0;if(expiry<=now||typeof x.latitude!=='number'||typeof x.longitude!=='number')return;sharedLocationPoints.push({uid:d.id,displayName:x.displayName||'SORO member',latitude:x.latitude,longitude:x.longitude,accuracy:typeof x.accuracy==='number'?x.accuracy:null,mine:d.id===auth.currentUser?.uid})});refreshSoroGlobePoints();const mine=snap.docs.find(d=>d.id===auth.currentUser?.uid&&((d.data().expiresAt?.toMillis?.()||0)>now));mapStopSharing.classList.toggle('hidden',!mine)}
function watchSharedLocations(){if(locationUnsubscribe||!auth.currentUser)return;locationUnsubscribe=onSnapshot(collection(db,'memberLocations'),renderSharedLocations,()=>{mapMessage.textContent='Could not load shared member locations.'})}
async function shareLocation(minutes){if(!navigator.geolocation){mapMessage.textContent='Location is not supported on this device.';return}mapMessage.textContent='Getting your precise location…';navigator.geolocation.getCurrentPosition(async pos=>{try{const expiresAt=new Date(Date.now()+minutes*60000);await setDoc(doc(db,'memberLocations',auth.currentUser.uid),{uid:auth.currentUser.uid,displayName:currentMember?.displayName||auth.currentUser.displayName||'Member',latitude:pos.coords.latitude,longitude:pos.coords.longitude,accuracy:pos.coords.accuracy,expiresAt,updatedAt:serverTimestamp()});mapMessage.textContent='Location shared for '+(minutes===60?'1 hour':minutes===240?'4 hours':'15 minutes')+'.';mapSharePanel.classList.add('hidden');mapStopSharing.classList.remove('hidden');ensureSoroGlobe();soroGlobe?.pointOfView({lat:pos.coords.latitude,lng:pos.coords.longitude,altitude:.00025},2200)}catch(err){console.error(err);mapMessage.textContent='Could not share location. '+(err.code||'')}},err=>{mapMessage.textContent=err.code===1?'Location permission was denied.':'Could not get your location.'},{enableHighAccuracy:true,timeout:12000,maximumAge:0})}
async function stopLocationSharing(){try{await deleteDoc(doc(db,'memberLocations',auth.currentUser.uid));mapStopSharing.classList.add('hidden');mapMessage.textContent='Location sharing stopped.'}catch(err){console.error(err);mapMessage.textContent='Could not stop sharing. '+(err.code||'')}}
document.querySelectorAll('[data-map-duration]').forEach(b=>b.addEventListener('click',()=>shareLocation(Number(b.dataset.mapDuration))));mapStopSharing?.addEventListener('click',stopLocationSharing);
